package com.runitebar.adventurerslog;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("adventurerslog")
public interface AdventurersLogConfig extends Config {
    @ConfigItem(
            keyName = "logData",
            name = "Log Data",
            description = "Stored log entries",
            hidden = true
    )
    default String logData() { return "[]"; }
}

package com.runitebar.adventurerslog;

import java.awt.*;
import java.util.List;
import javax.swing.*;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import javax.inject.Singleton;

import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.api.SpriteID;
import net.runelite.client.game.SpriteManager;

import javax.swing.ImageIcon;

@Singleton
public class AdventurersLogPanel extends PluginPanel {
    private final JPanel logContainer = new JPanel();
    private final SkillIconManager skillIconManager;
    private final ItemManager itemManager;
    private final SpriteManager spriteManager;

    public AdventurersLogPanel(SkillIconManager skillIconManager, ItemManager itemManager, SpriteManager spriteManager) {
        super();
        this.skillIconManager = skillIconManager;
        this.itemManager = itemManager;
        this.spriteManager = spriteManager;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // Header Section
        JPanel header = new JPanel(new GridBagLayout());
        header.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        header.setPreferredSize(new Dimension(0, 40));
        header.setBorder(new MatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR));

        JLabel title = new JLabel("Adventurer's Log");
        title.setForeground(ColorScheme.BRAND_ORANGE);
        title.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 16));

        title.setHorizontalAlignment(SwingConstants.CENTER);
        title.setVerticalAlignment(SwingConstants.CENTER);

        header.add(title);
        add(header, BorderLayout.NORTH);

        // Log Container
        logContainer.setLayout(new BoxLayout(logContainer, BoxLayout.Y_AXIS));
        logContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JScrollPane scrollPane = new JScrollPane(logContainer);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(null);
        add(scrollPane, BorderLayout.CENTER);
    }

    public void rebuild(List<LogEntry> entries) {
        logContainer.removeAll();

        logContainer.add(Box.createRigidArea(new Dimension(0, 5)));

        for (int i = entries.size() - 1; i >= 0; i--) {
            logContainer.add(createEntryPanel(entries.get(i)));

            logContainer.add(Box.createRigidArea(new Dimension(0, 5)));
        }

        revalidate();
        repaint();
    }

    private JPanel createEntryPanel(LogEntry entry) {
        JPanel panel = new JPanel(new BorderLayout(10, 0));
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(new CompoundBorder(
                new MatteBorder(1, 1, 1, 1, ColorScheme.DARK_GRAY_COLOR),
                new EmptyBorder(8, 8, 8, 8)
        ));

        JLabel iconLabel = new JLabel();
        iconLabel.setPreferredSize(new Dimension(32, 32));
        iconLabel.setHorizontalAlignment(SwingConstants.CENTER);

        if (entry.getType().equals("LEVEL")) {
            try {
                Skill skill = Skill.valueOf(entry.getSubType().toUpperCase());
                iconLabel.setIcon(new ImageIcon(skillIconManager.getSkillImage(skill, true)));
            } catch (Exception e) {}
        }
        else if (entry.getType().equals("QUEST")) {
            java.awt.image.BufferedImage img = spriteManager.getSprite(SpriteID.TAB_QUESTS, 0);
            if (img != null) {
                iconLabel.setIcon(new ImageIcon(img));
            }
        }
        else if (entry.getType().equals("CLOG")) {
            iconLabel.setIcon(new ImageIcon(itemManager.getImage(22711)));
        }

// Text Content
        JPanel textPanel = new JPanel(new GridLayout(2, 1));
        textPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        String displayMsg = entry.getMessage();
        if (entry.getCount() > 1) {
            displayMsg += " <span style='color:#ffff00'>(x" + entry.getCount() + ")</span>";
        }

        JLabel msgLabel = new JLabel("<html><body style='width: 130px'>" + displayMsg + "</body></html>");
        msgLabel.setForeground(Color.WHITE);
        msgLabel.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));

        JLabel dateLabel = new JLabel(entry.getTimestamp());
        dateLabel.setFont(new Font(Font.SANS_SERIF, Font.ITALIC, 11));
        dateLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        textPanel.add(msgLabel);
        textPanel.add(dateLabel);

        panel.add(iconLabel, BorderLayout.WEST);
        panel.add(textPanel, BorderLayout.CENTER);

        panel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, panel.getPreferredSize().height));

        return panel;
    }
}

package com.runitebar.adventurerslog;

import lombok.Data;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

@Data
public class LogEntry {
    private final String timestamp; // The full time (e.g., "Oct 25, 14:30")
    private final String date;      // Just the date (e.g., "2024-10-25")
    private final String message;   // The base message (e.g., "Killed Zulrah")
    private final String type;      // LEVEL, BOSS, etc.
    private final String subType;   // The boss/skill name
    private int count;              // How many times this happened today

    public LogEntry(String type, String message, String subType) {
        this.timestamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("MMM dd, HH:mm"));
        this.date = LocalDate.now().toString(); // "2024-10-25"
        this.message = message;
        this.type = type;
        this.subType = subType;
        this.count = 1;
    }
}

package com.runitebar.adventurerslog;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.game.SpriteManager;
import java.time.LocalDate;

@Singleton
@PluginDescriptor(
        name = "Adventurer's Log",
        description = "Tracks levels, quests, bosses, and milestones",
        tags = {"history", "log", "boss", "quest"}
)
public class AdventurersLogPlugin extends Plugin {
    @Inject private Client client;
    @Inject private AdventurersLogConfig config;
    @Inject private ConfigManager configManager;
    @Inject private ClientToolbar clientToolbar;
    @Inject private SkillIconManager skillIconManager;
    @Inject private ItemManager itemManager; // Added
    @Inject private Gson gson;
    @Inject private SpriteManager spriteManager;

    private AdventurersLogPanel panel;
    private NavigationButton navButton;
    private List<LogEntry> logEntries = new ArrayList<>();
    private final int[] lastLevels = new int[23];

    @Override
    protected void startUp() {
        logEntries = gson.fromJson(config.logData(), new TypeToken<List<LogEntry>>(){}.getType());
        if (logEntries == null) logEntries = new ArrayList<>();

        panel = new AdventurersLogPanel(skillIconManager, itemManager, spriteManager);
        panel.rebuild(logEntries);

        navButton = NavigationButton.builder()
                .tooltip("Adventurer's Log")
                .icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
                .priority(10)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown() {
        clientToolbar.removeNavigation(navButton);
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        int idx = event.getSkill().ordinal();
        int currentLevel = event.getLevel();

        if (lastLevels[idx] != 0 && currentLevel > lastLevels[idx]) {
            String skillName = event.getSkill().getName();
            addEntry(new LogEntry("LEVEL", "Gained level " + currentLevel + " " + skillName, skillName));
        }
        lastLevels[idx] = currentLevel;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        String msg = event.getMessage();

        // 1. Boss Kill Count
        if ((msg.contains("kill count is:") || msg.contains("completion count is:")) && msg.contains("Your")) {
            String cleaned = msg.replaceAll("<[^>]*>", "");
            String bossName = cleaned.split("Your ")[1].split(" (kill|completion)")[0];

            handleBossKill(bossName);
        }

        // 2. Quest Completion
        if (msg.contains("You have completed the quest:") || msg.contains("You have completed a quest:")) {
            String questName = msg.split(": ")[1].replace(".", "");
            addEntry(new LogEntry("QUEST", "Quest Completed: " + questName, "QUEST_POINT"));
        }

        // 3. Collection Log
        if (msg.contains("New item added to your collection log:")) {
            String item = msg.split(": ")[1];
            addEntry(new LogEntry("CLOG", "Collection Log: " + item, "CLOG"));
        }
    }

    private void handleBossKill(String bossName) {
        String today = LocalDate.now().toString();

        // Look for an existing entry for this boss from today
        LogEntry existing = logEntries.stream()
                .filter(e -> e.getType().equals("BOSS")
                        && e.getSubType().equalsIgnoreCase(bossName)
                        && e.getDate().equals(today))
                .findFirst()
                .orElse(null);

        if (existing != null) {
            // Increment the count of the existing entry
            existing.setCount(existing.getCount() + 1);
            saveAndRefresh();
        } else {
            // Create a new entry for the first kill of the day
            addEntry(new LogEntry("BOSS", "Killed " + bossName, bossName));
        }
    }

    private void addEntry(LogEntry entry) {
        logEntries.add(entry);
        if (logEntries.size() > 150) logEntries.remove(0);
        saveAndRefresh();
    }

    private void saveAndRefresh() {
        configManager.setConfiguration("adventurerslog", "logData", gson.toJson(logEntries));
        SwingUtilities.invokeLater(() -> panel.rebuild(logEntries));
    }

    @Provides
    AdventurersLogConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(AdventurersLogConfig.class);
    }
}
